from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags
from tests.conftest import make_task


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_add_and_get(self, repo):
        task = make_task(id=1)
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(make_task(id=1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1))

    def test_list_returns_all(self, repo):
        for i in range(1, 4):
            repo.add(make_task(id=i, title=f"Task {i}"))
        items = list(repo.list())
        assert len(items) == 3

    def test_update_existing(self, repo):
        task = make_task(id=1, title="old")
        repo.add(task)
        task.title = "new"
        repo.update(task)
        assert repo.get(1).title == "new"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates_by_name(self):
        result = normalize_tags([Tag("urgent"), Tag("URGENT")])
        assert len(result) == 1
        assert result[0].name == "urgent"

    def test_accepts_strings(self):
        result = normalize_tags(["Bug", "feature"])
        assert [t.name for t in result] == ["bug", "feature"]

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["c", "a", "b", "A"])
        assert [t.name for t in result] == ["c", "a", "b"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

"""Tests for tasks_api.queries — TaskQuery, apply_query, filtering, sorting, pagination."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query
from tests.conftest import FIXED_NOW, make_task


NOW = FIXED_NOW


# ── TaskQuery validation ─────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_default_values(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("bad_sort", ["id", "unknown", ""])
    def test_invalid_sort_field(self, bad_sort):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort=bad_sort)

    @pytest.mark.parametrize("bad_limit", [0, -1, 101, "ten"])
    def test_invalid_limit(self, bad_limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=bad_limit)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  Urgent  ")
        assert q.tag == "urgent"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_blank_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


# ── TaskPage.has_more ────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[make_task()], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[make_task()], total=1, limit=20, offset=0)
        assert page.has_more is False

    def test_has_more_false_exact_boundary(self):
        items = [make_task(id=i) for i in range(1, 4)]
        page = TaskPage(items=items, total=3, limit=3, offset=0)
        assert page.has_more is False


# ── apply_query filtering ────────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        past = NOW - timedelta(hours=1)
        future = NOW + timedelta(hours=1)
        return [
            make_task(id=1, title="Buy milk", status=TaskStatus.PENDING, due_at=past, tags=[Tag("errand")]),
            make_task(id=2, title="Write docs", status=TaskStatus.DONE, tags=[Tag("work")]),
            make_task(id=3, title="Fix bug", status=TaskStatus.PENDING, due_at=future, tags=[Tag("work"), Tag("errand")]),
        ]

    def test_no_filter(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 3

    def test_filter_by_status(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="work"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {2, 3}

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="bug"), NOW)
        assert page.total == 1
        assert page.items[0].id == 3

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="BUY"), NOW)
        assert page.total == 1

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {2, 3}

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="errand"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 3}


# ── apply_query sorting ──────────────────────────────────────────────

class TestApplyQuerySorting:
    @pytest.fixture
    def tasks(self):
        return [
            make_task(id=1, title="Charlie", priority=TaskPriority.LOW,
                      created_at=NOW - timedelta(hours=2), due_at=NOW + timedelta(days=3)),
            make_task(id=2, title="Alpha", priority=TaskPriority.HIGH,
                      created_at=NOW - timedelta(hours=1), due_at=NOW + timedelta(days=1)),
            make_task(id=3, title="Bravo", priority=TaskPriority.MEDIUM,
                      created_at=NOW, due_at=None),
        ]

    def test_sort_by_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 2, 3]

    def test_sort_by_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), NOW)
        assert [t.id for t in page.items] == [3, 2, 1]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Alpha", "Bravo", "Charlie"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW
        ]

    def test_sort_by_due_at_none_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert page.items[-1].id == 3  # None due_at sorts last


# ── apply_query pagination ───────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [make_task(id=i, title=f"Task {i}",
                          created_at=NOW + timedelta(minutes=i)) for i in range(1, 8)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 7
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=5), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 7
        assert page.has_more is False

